N = 78
board = {}

# Fill the board row by row
for i in range(1, N + 1):
    for j in range(1, N + 1):
        value = (i - 1) * N + j
        board[(i, j)] = value

def is_starting_point(r, c):
    value = board[(r, c)]

    # Possible neighbors (dr, dc): Up, Down, Left, Right
    neighbors = [
        (r - 1, c),  # Up
        (r + 1, c),  # Down
        (r, c - 1),  # Left
        (r, c + 1)   # Right
    ]

    for nr, nc in neighbors:
        # Check if neighbor is within bounds
        if 1 <= nr <= N and 1 <= nc <= N:
            neighbor_value = board[(nr, nc)]
            # Condition (i) requires ALL adjacent fields to have LARGER numbers.
            # If we find one smaller or equal, it's not a starting point.
            if neighbor_value <= value:
                return False
    return True

# Check every cell
starting_points = []
for r in range(1, N + 1):
    for c in range(1, N + 1):
        if is_starting_point(r, c):
            starting_points.append((r, c))

print(f"Number of starting points found: {len(starting_points)}")
if starting_points:
    print(f"Coordinates of starting points: {starting_points}")

